    var REG_ANS = [90090, 90091, 90092, 90093], ALT_ANS = [90200, 90201, 90202, 90203];
    var ALT_TEXT = "You’re out here on the debate stage at Case Western Reserve in what you hope to be a much more tame debate than four years ago. Chris Wallace asks about Marco Rubio’s calls to expand the Supreme Court following your unprecedented three appointees making it to the nation's highest court. Wallace asks why your opposition to this idea is correct, and Marco Rubio’s position is wrong.";
    var q = t.questions_json.find(function (x) { return x.pk === Q; });
